import{b as e}from"./index-Nu8wENgH.js";import{t}from"./personagens-pt-Dax9UsHX.js";var n={pt:t,en:JSON.parse(`[{"id":"kim","nome":"Kim","nomeCompleto":"Joaquim Leal Reis","apelido":"Brawler 142536 / The Primordial","idade":17,"status":"alive","grupo":"protagonist","ranking":"1,201","arma":"Xakixi","estilo":"Street fighting + Primordial Blood","elemental":"Fire / Darkness","descricaoBreve":"17 years old. Xakaxi descendant. Sells candy on buses, scholarship student at Elite Academy. Carries something ancestral he never asked for and can't control.","descricaoCompleta":"Kim grew up with no past and no father. Helena, the woman who raised him, was twelve years old when she saved him from a place neither of them should have survived. Since he was twelve, Kim has been supporting the household selling candy on buses. He earned a spot at Elite Academy through Osvaldo, the school's gatekeeper. In LDI, his first fight went viral worldwide — not because of the victory, but because of what emerged before it. Something ancestral. Something that doesn't ask permission.","frase":"I don't beg. Not for anyone. Never.","imagem":"/assets/images/characters/kim.png","relacoes":[{"personagem":"Jack","tipo":"Best friend, brother"},{"personagem":"Helena","tipo":"Adoptive mother"},{"personagem":"Nina","tipo":"Friend, mutual attraction"},{"personagem":"Pajé Yawanari","tipo":"Spiritual guide"},{"personagem":"David Kronos","tipo":"Main antagonist"}]},{"id":"jack","nome":"Jack","nomeCompleto":"Jack","apelido":"Jack Cachorrão 987654321","idade":17,"status":"alive","grupo":"protagonist","ranking":"10,776","arma":"Vitória","estilo":"Cane fighting / San Tien Kwan","elemental":"Stone","descricaoBreve":"17 years old. Green dreads. Films everything, laughs at everything, and is far more dangerous than he looks.","descricaoCompleta":"Jack is the kind of person who seems reckless until you see him fight. Green dreads, always with his phone out, always pointing a camera at the most inconvenient moment. He's been Kim's best friend since they were twelve — the only person in the world Kim can't push away. In LDI he developed a unique style built around his cane Vitória, which in Shaman mode becomes the San Tien Kwan. Theatrical in life, precise in battle.","frase":"I needed this so much. This is going to be eternal, I swear on everything.","imagem":"/assets/images/characters/jack.png","relacoes":[{"personagem":"Kim","tipo":"Best friend, brother"},{"personagem":"Nina","tipo":"Friend, constant comic tension"}]},{"id":"nina","nome":"Nina","nomeCompleto":"Nina","apelido":"","idade":null,"status":"alive","grupo":"protagonist","ranking":"8,724","arma":"Angel","estilo":"Muay Thai + Katana","elemental":"Water","descricaoBreve":"Arrived without warning. Angel katana, Muay Thai, and a past she doesn't explain.","descricaoCompleta":"Nina walked into Elite Academy's classroom mid-lesson and evaluated everyone before sitting down. She spent four years in Azuma because of her father's work — work she describes as consulting, with a pause before the word. Direct, economical with words. When she speaks, the scene changes. She defeated Kim in their first serious fight and has been an inseparable part of the trio ever since.","frase":"I'm afraid you two aren't man enough to handle it.","imagem":"/assets/images/characters/nina.png","relacoes":[{"personagem":"Kim","tipo":"Friend, mutual attraction"},{"personagem":"Jack","tipo":"Friend, constant comic tension"}]},{"id":"helena","nome":"Helena","nomeCompleto":"Helena","apelido":"Dona Helena","idade":null,"status":"alive","grupo":"supporting","ranking":null,"arma":null,"estilo":null,"elemental":null,"descricaoBreve":"Kim's adoptive mother. Not by choice — by instinct. She was twelve years old when she ran with him in her arms.","descricaoCompleta":"Helena has no memory before a certain point. The oldest place she remembers is a room with a nearly dead lightbulb. She was around twelve when a newborn appeared in that room and she understood what was going to happen. She ran that same night. The years that followed were what they were. Today she uses alcohol as an anesthetic and Kim pays the bills. Their relationship is a minefield with rare solid ground — but the ground exists.","frase":"You were such a beautiful baby, you know. So beautiful and so chubby. Like a little ball.","imagem":"/assets/images/characters/helena.png","relacoes":[{"personagem":"Kim","tipo":"Adoptive son"}]},{"id":"yawanari","nome":"Pajé Yawanari","nomeCompleto":"Pajé Yawanari","apelido":"","idade":null,"status":"immortal","grupo":"supporting","ranking":null,"arma":"Berimbau","estilo":"Ancestral shamanism","elemental":null,"descricaoBreve":"Immortal shaman of the Xakaxi tribe. Guardian of the seal for 500 years. Ancestral wisdom sharing space with pop culture.","descricaoCompleta":"Immortal shaman of the Xakaxi tribe. He chose to remain trapped in the seal as a voluntary guardian 500 years ago, while the world outside changed in ways he wasn't prepared to process. Five centuries watching humanity without being able to intervene did things to his mind. The ancestral wisdom is still there, intact, deeper than anything alive today can reach. The problem is that it now shares space with five hundred years of pop culture absorbed through a spiritual rift, and both come out of the same mouth without warning. He appears when he wants, leaves when he's done, talks to partners only he can see, and considers the berimbau a fashion accessory. The bowler hat has been his for two hundred years. The chain with DIX is recent. When he stops joking and speaks seriously, the whole room changes temperature. He is the only living being who knows exactly what Kim carries, what Voa plans, and what the seal cost. He'll share it when he thinks the time is right, not before.","frase":"I showed up to slay! Damn, you're really messed up, bro.","imagem":"/assets/images/characters/yawanari.png","relacoes":[{"personagem":"Kim","tipo":"Protégé / heir of Xakaxi legacy"},{"personagem":"David Kronos (Voa)","tipo":"Five-century enemy"}]},{"id":"kronos","nome":"David Kronos","nomeCompleto":"David Kronos","apelido":"","idade":null,"status":"alive","grupo":"antagonist","ranking":null,"arma":null,"estilo":"Corrupted ancestral spirit — Voa","elemental":null,"descricaoBreve":"Corrupted ancestral spirit who waited centuries. Kim is the bearer of the Primordial Blood.","descricaoCompleta":"David Kronos is the current name of Voa, a corrupted ancestral spirit who refused the sealing performed by Pajé Yawanari and the Xakaxi people 500 years ago. While Yawanari was trapped as a voluntary guardian of the seal, Voa was trapped as a consequence of his own refusal. Over centuries he learned to incarnate in human bodies, always of indigenous descent because they are the only ones that can withstand his soul's power without collapsing immediately. He calls bodies without Primordial Blood impure: they work for a limited time before drying up. He discovered that modern technology could be used to access the powers of the ancient era. LDI is not a game: it's an intermediary between the sealed real world and the plane where original magic still exists. It was Voa who found this intermediary and built Yohualticit around it. Objective: use a body with Primordial Blood as a portal. Through this portal, all the powers the Xakaxi tribe once held would pass through the body and be released into the world, breaking the seal, giving Voa absolute dominion and revenge over everything that imprisoned him. Kim is the only identified bearer of pure Primordial Blood. Helena's background, with no known father, is the layer that hides the lineage. Current body: David Kronos, middle-aged appearance, marked indigenous features, black hair tied with shaved sides, dense physique suggesting the body was chosen and not just found. White suit, presence of someone who built an empire on centuries of patience.","frase":"He will be mine. Regardless of the price.","imagem":"/assets/images/characters/kronos.png","relacoes":[{"personagem":"Kim","tipo":"Main antagonist — seeks the Primordial Blood"},{"personagem":"Pajé Yawanari","tipo":"Five-century enemy"}]},{"id":"shuntaro","nome":"Shuntaro","nomeCompleto":"Shuntaro Chirasu","apelido":"","idade":null,"status":"alive","grupo":"rival","ranking":"998","arma":"Metal yo-yos","estilo":"Multiple Water Balls / Rei Xamã","elemental":"Water","descricaoBreve":"Came from Azuma specifically to fight Kim. Nine hours of travel. He didn't come to lose.","descricaoCompleta":"Shuntaro Chirasu is the highest-ranked opponent Kim has faced — world position 998. He arrived at Elite Academy unannounced, introduced himself with genuine courtesy, and issued the challenge in the same breath. There's real respect in his eyes, alongside the quiet certainty of someone who knows they're stronger. The fight between them ended without a declared winner — in the most interesting way possible.","frase":"I came from Azuma specifically for this. Nine hours of travel.","imagem":"/assets/images/characters/shuntaro.png","relacoes":[{"personagem":"Kim","tipo":"Respectful rival"},{"personagem":"Nina","tipo":"Connection from Azuma"}]},{"id":"lisa","nome":"Lisa","nomeCompleto":"Lisa","apelido":"","idade":"17-19","status":"alive","grupo":"rival","ranking":"top 500","arma":"Microphone","estilo":"Singer / Shaman (in development)","elemental":"Ice","descricaoBreve":"Top 500 worldwide. Global artist. Sings, dances, fights. Kim's romantic interest.","descricaoCompleta":"Born in Marelia, Bravara. Left as a child. Grew up in transit between music markets, established her career in Nortalis, Valdera — the epicenter of the global pop industry in the LDI universe. A global artist, based between Nortalis and wherever the schedule demands. Long curly dark brown hair, brown skin, hoop earrings, posture of someone trained to command a stage. Offstage, comfortable, nothing performative. Top 500 worldwide — a real-level fighter, not a background character. Elemental: Ice. Phase 1 weapon: microphone (normal and shaman mode to be developed). Phase 2 weapon: open. Future collaboration with the trio: she sings, Jack raps, Nina duets. Appears in book 2, outside Bravara, during the trio's exile. Enters challenging Kim because she doesn't believe he deserves the hype. Anchors the romantic quartet with all the comedic chaos that precedes any resolution.","frase":"","imagem":"/assets/images/characters/lisa.png","relacoes":[{"personagem":"Kim","tipo":"Romantic interest / LDI rival"},{"personagem":"Jack","tipo":"Musical partner (rap)"},{"personagem":"Nina","tipo":"Musical duet"}]},{"id":"voidhunter","nome":"VoidHunter_X","nomeCompleto":"VoidHunter_X","apelido":"","idade":null,"status":"defeated","grupo":"antagonist","ranking":null,"arma":"Black ooze / chest fissures","estilo":"Unknown — not a player","elemental":"Darkness","descricaoBreve":"Kim's first opponent in LDI. The movements are wrong. The neck turns too far. The visor reflects nothing.","descricaoCompleta":"VoidHunter_X appeared in Kim's dream before appearing in reality. Near-black armor with exaggeratedly wide pauldrons, arms too long, fingers that bend the wrong way. The visor is a horizontal slit with an amber gradient at the edges darkening toward the center — no reflection, no void, just an intrinsic light that shouldn't be there. Fissures in the chest leak a dark ooze. When Kim tore off the helmet, underneath was more armor. Identical, smaller, nested inside.","frase":"","imagem":"/assets/images/characters/voidhunter.png","relacoes":[{"personagem":"Kim","tipo":"First opponent — prologue"},{"personagem":"David Kronos","tipo":"Possible connection"}]},{"id":"alan","nome":"Alan","nomeCompleto":"Alan","apelido":"The Champion","idade":18,"status":"alive","grupo":"rival","ranking":null,"arma":null,"estilo":"Organized crime","elemental":null,"descricaoBreve":"Eighteen years old. Leader of organized crime in Marelia. The rival who taught that some fights can't be won, only survived.","descricaoCompleta":"Eighteen years old. Leader of organized crime across an entire region of Marelia. Alan didn't get where he is through inheritance or connections. He got there because he was the street kid nobody could break, and when the crime world realized that, it was only a matter of time. Security, enforcer, boss, boss of bosses. One step at a time, each earned the only way that world recognizes. Kim and Jack fought him for years. They lost. Came back. Lost again. Never won, but also never stopped, and Alan remembered that. When the duo's fame in LDI starts affecting his business, Alan doesn't act out of anger. He acts because visible weakness in a world like his has a price. The final encounter doesn't end in defeat or victory. It ends in a draw that both know means respect, and a deal: leave Marelia, preferably the country, and he guarantees protection for those left behind. He's not an antagonist. He's the rival who taught that some fights can't be won, only survived.","frase":"","imagem":"/assets/images/characters/alan.png","relacoes":[{"personagem":"Kim","tipo":"Historical rival / mutual respect"},{"personagem":"Jack","tipo":"Historical rival / mutual respect"}]}]`),es:JSON.parse(`[{"id":"kim","nome":"Kim","nomeCompleto":"Joaquim Leal Reis","apelido":"Peleador 142536 / El Primordial","idade":17,"status":"vivo","grupo":"protagonista","ranking":"1.201","arma":"Xakixi","estilo":"Combate callejero + Sangre Primordial","elemental":"Fuego / Oscuridad","descricaoBreve":"17 años. Descendiente Xakaxi. Vende dulces en autobuses, becado en Elite Academy. Carga algo ancestral que nunca pidió y no puede controlar.","descricaoCompleta":"Kim creció sin pasado y sin padre. Helena, la mujer que lo crió, tenía doce años cuando lo salvó de un lugar del que ninguno de los dos debería haber salido. Desde los doce años Kim mantiene la casa vendiendo dulces en autobuses. Consiguió un lugar en Elite Academy gracias a Osvaldo, el portero. En LDI, su primera pelea se volvió viral en todo el mundo — no por la victoria, sino por lo que emergió antes. Algo ancestral. Algo que no pide permiso.","frase":"No suplico. A nadie. Nunca.","imagem":"/assets/images/characters/kim.png","relacoes":[{"personagem":"Jack","tipo":"Mejor amigo, hermano"},{"personagem":"Helena","tipo":"Madre adoptiva"},{"personagem":"Nina","tipo":"Amiga, atracción mutua"},{"personagem":"Pajé Yawanari","tipo":"Guía espiritual"},{"personagem":"David Kronos","tipo":"Antagonista principal"}]},{"id":"jack","nome":"Jack","nomeCompleto":"Jack","apelido":"Jack Cachorrão 987654321","idade":17,"status":"vivo","grupo":"protagonista","ranking":"10.776","arma":"Vitória","estilo":"Bastón / San Tien Kwan","elemental":"Piedra","descricaoBreve":"17 años. Rastas verdes. Filma todo, se ríe de todo, y es mucho más peligroso de lo que parece.","descricaoCompleta":"Jack es el tipo de persona que parece imprudente hasta que lo ves pelear. Rastas verdes, siempre con el teléfono en mano, siempre apuntando una cámara al momento más inconveniente. Es el mejor amigo de Kim desde los doce años y la única persona en el mundo que Kim no puede alejar. En LDI desarrolló un estilo único basado en su bastón Vitória, que en modo Chamán se convierte en San Tien Kwan. Teatral en la vida, preciso en la batalla.","frase":"Necesitaba esto muchísimo. Va a ser eterno, lo juro por todo.","imagem":"/assets/images/characters/jack.png","relacoes":[{"personagem":"Kim","tipo":"Mejor amigo, hermano"},{"personagem":"Nina","tipo":"Amiga, tensión cómica constante"}]},{"id":"nina","nome":"Nina","nomeCompleto":"Nina","apelido":"","idade":null,"status":"viva","grupo":"protagonista","ranking":"8.724","arma":"Angel","estilo":"Muay Thai + Katana","elemental":"Agua","descricaoBreve":"Llegó sin avisar. Katana Angel, Muay Thai, y un pasado que no explica.","descricaoCompleta":"Nina entró al salón de Elite Academy a mitad de clase y evaluó a todos antes de sentarse. Pasó cuatro años en Azuma por el trabajo de su padre — un trabajo que describe como consultoría, con una pausa antes de la palabra. Directa al punto, económica con las palabras. Cuando habla, la escena cambia. Derrotó a Kim en su primera pelea seria y desde entonces es parte inseparable del trío.","frase":"Me temo que ustedes dos todavía no son suficientemente hombres para lidiar conmigo.","imagem":"/assets/images/characters/nina.png","relacoes":[{"personagem":"Kim","tipo":"Amiga, atracción mutua"},{"personagem":"Jack","tipo":"Amigo, tensión cómica constante"}]},{"id":"helena","nome":"Helena","nomeCompleto":"Helena","apelido":"Doña Helena","idade":null,"status":"viva","grupo":"apoyo","ranking":null,"arma":null,"estilo":null,"elemental":null,"descricaoBreve":"Madre adoptiva de Kim. No por elección — por instinto. Tenía doce años cuando huyó con él en brazos.","descricaoCompleta":"Helena no tiene memoria de antes de cierto punto. El lugar más antiguo que recuerda es una habitación con una bombilla casi apagada. Tenía alrededor de doce años cuando apareció un bebé en esa habitación y entendió lo que iba a pasar. Huyó esa misma noche. Los años que siguieron fueron lo que fueron. Hoy usa el alcohol como anestésico y Kim paga las facturas. La relación entre ellos es un campo minado con raros terrenos sólidos — pero el terreno existe.","frase":"Eras un bebé hermosísimo, ¿sabes? Muy lindo y muy gordito. Parecías una bolita.","imagem":"/assets/images/characters/helena.png","relacoes":[{"personagem":"Kim","tipo":"Hijo adoptivo"}]},{"id":"yawanari","nome":"Pajé Yawanari","nomeCompleto":"Pajé Yawanari","apelido":"","idade":null,"status":"inmortal","grupo":"apoyo","ranking":null,"arma":"Berimbau","estilo":"Chamanismo ancestral","elemental":null,"descricaoBreve":"Chamán inmortal de la tribu Xakaxi. Guardián del sellamiento por 500 años. La sabiduría ancestral comparte espacio con la cultura pop.","descricaoCompleta":"Chamán inmortal de la tribu Xakaxi. Eligió quedar atrapado en el sellamiento como guardián voluntario hace 500 años, mientras el mundo exterior cambiaba de formas que no estaba preparado para procesar. Cinco siglos observando a la humanidad sin poder intervenir hicieron cosas en su cabeza. La sabiduría ancestral sigue ahí, intacta, más profunda que cualquier cosa viva hoy pueda alcanzar. El problema es que ahora comparte espacio con quinientos años de cultura pop absorbida a través de una grieta espiritual, y ambas cosas salen por la misma boca sin aviso. Aparece cuando quiere, desaparece cuando termina, habla con compañeros que solo él ve, y considera el berimbau un accesorio de moda. El sombrero bombín es suyo desde hace doscientos años. El cordón con DIX es reciente. Cuando deja de bromear y habla en serio, la sala entera cambia de temperatura. Es el único ser vivo que sabe exactamente qué carga Kim, qué planea Voa, y qué costó el sellamiento. Lo contará cuando crea que es el momento adecuado, no antes.","frase":"¡Vine a brillar! ¡Dios mío, estás hecho un desastre, bro!","imagem":"/assets/images/characters/yawanari.png","relacoes":[{"personagem":"Kim","tipo":"Protegido / heredero del legado Xakaxi"},{"personagem":"David Kronos (Voa)","tipo":"Enemigo de cinco siglos"}]},{"id":"kronos","nome":"David Kronos","nomeCompleto":"David Kronos","apelido":"","idade":null,"status":"vivo","grupo":"antagonista","ranking":null,"arma":null,"estilo":"Espíritu ancestral corrompido — Voa","elemental":null,"descricaoBreve":"Espíritu ancestral corrompido que esperó siglos. Kim es el portador de la Sangre Primordial.","descricaoCompleta":"David Kronos es el nombre actual de Voa, un espíritu ancestral corrompido que se negó al sellamiento realizado por el Pajé Yawanari y los pueblos Xakaxi hace 500 años. Mientras Yawanari quedó atrapado como guardián voluntario del sellamiento, Voa quedó atrapado como consecuencia de su propio rechazo. Aprendió a lo largo de siglos a encarnar en cuerpos humanos, siempre de descendencia indígena porque son los únicos que soportan la fuerza de su alma sin colapsar inmediatamente. Llama a los cuerpos sin Sangre Primordial impuros: funcionan por tiempo limitado antes de secarse. Descubrió que la tecnología moderna podía usarse para acceder a los poderes de la era antigua. El LDI no es un juego: es un intermediario entre el mundo real sellado y el plano donde la magia original aún existe. Fue Voa quien encontró este intermediario y construyó Yohualticit a su alrededor. Objetivo: usar un cuerpo con Sangre Primordial como portal. A través de ese portal, todos los poderes que la tribu Xakaxi alguna vez tuvo pasarían por el cuerpo y serían liberados en el mundo, rompiendo el sellamiento, dándole a Voa dominio absoluto y venganza sobre todo lo que lo aprisionó. Kim es el único portador de Sangre Primordial pura identificado. El trasfondo de Helena, sin padre conocido, es la capa que esconde el linaje. Cuerpo actual: David Kronos, apariencia de hombre de mediana edad, rasgos indígenas marcados, cabello negro atado con los lados rapados, físico denso que sugiere que el cuerpo fue elegido y no solo encontrado. Traje blanco, presencia de quien construyó un imperio sobre paciencia de siglos.","frase":"Será mío. Sin importar el precio.","imagem":"/assets/images/characters/kronos.png","relacoes":[{"personagem":"Kim","tipo":"Antagonista principal — busca la Sangre Primordial"},{"personagem":"Pajé Yawanari","tipo":"Enemigo de cinco siglos"}]},{"id":"shuntaro","nome":"Shuntaro","nomeCompleto":"Shuntaro Chirasu","apelido":"","idade":null,"status":"vivo","grupo":"rival","ranking":"998","arma":"Yoyós de metal","estilo":"Multiple Water Balls / Rei Xamã","elemental":"Agua","descricaoBreve":"Vino de Azuma específicamente para pelear con Kim. Nueve horas de viaje. No vino a perder.","descricaoCompleta":"Shuntaro Chirasu es el rival de mayor rango que Kim ha enfrentado hasta ahora — posición 998 mundial. Llegó a Elite Academy sin anunciarse, se presentó con cortesía genuina y lanzó el desafío en la misma frase. Hay respeto real en su mirada, junto con la tranquila certeza de alguien que sabe que es más fuerte. La pelea entre ellos terminó sin un ganador declarado — de la manera más interesante posible.","frase":"Vine de Azuma específicamente para esto. Nueve horas de viaje.","imagem":"/assets/images/characters/shuntaro.png","relacoes":[{"personagem":"Kim","tipo":"Rival respetuoso"},{"personagem":"Nina","tipo":"Conexión de Azuma"}]},{"id":"lisa","nome":"Lisa","nomeCompleto":"Lisa","apelido":"","idade":"17-19","status":"viva","grupo":"rival","ranking":"top 500","arma":"Micrófono","estilo":"Cantante / Chamán (en desarrollo)","elemental":"Hielo","descricaoBreve":"Top 500 mundial. Artista global. Canta, baila, lucha. Interés romántico de Kim.","descricaoCompleta":"Nació en Marelia, Bravara. Salió aún niña. Creció en tránsito entre mercados musicales, estableció su carrera en Nortalis, Valdera — el epicentro de la industria pop mundial en el universo LDI. Artista global, basada entre Nortalis y donde la agenda mande. Cabello largo rizado castaño oscuro, piel morena, argollas en las orejas, postura de quien fue entrenada para ocupar un escenario. Fuera del escenario, cómoda, nada performática. Top 500 mundial — luchadora de nivel real, no figurante. Elemental: Hielo. Arma fase 1: micrófono (modo normal y chamán a desarrollar). Arma fase 2: abierta. Colaboración futura con el trío: ella canta, Jack rapea, Nina en dueto. Aparece en el libro 2, fuera de Bravara, durante el exilio del trío. Entra desafiando a Kim porque no cree que merezca el hype. Ancla el cuarteto romántico con todo el caos cómico que antecede cualquier resolución.","frase":"","imagem":"/assets/images/characters/lisa.png","relacoes":[{"personagem":"Kim","tipo":"Interés romántico / rival en LDI"},{"personagem":"Jack","tipo":"Compañero musical (rap)"},{"personagem":"Nina","tipo":"Dúo musical"}]},{"id":"voidhunter","nome":"VoidHunter_X","nomeCompleto":"VoidHunter_X","apelido":"","idade":null,"status":"derrotado","grupo":"antagonista","ranking":null,"arma":"Limo negro / fisuras en el pecho","estilo":"Desconocido — no es un jugador","elemental":"Oscuridad","descricaoBreve":"El primer oponente de Kim en LDI. Los movimientos están mal. El cuello gira demasiado lejos. La visera no refleja nada.","descricaoCompleta":"VoidHunter_X apareció en el sueño de Kim antes de aparecer en la realidad. Armadura casi negra con hombreras exageradamente anchas, brazos demasiado largos, dedos que doblan en la dirección equivocada. La visera es una ranura horizontal con un degradado ámbar en los bordes oscureciéndose hacia el centro — sin reflejo, sin vacío, solo una luz intrínseca que no debería estar ahí. Las fisuras en el pecho dejan escapar un limo oscuro. Cuando Kim arrancó el casco, debajo había más armadura. Idéntica, más pequeña, anidada dentro.","frase":"","imagem":"/assets/images/characters/voidhunter.png","relacoes":[{"personagem":"Kim","tipo":"Primer oponente — prólogo"},{"personagem":"David Kronos","tipo":"Posible conexión"}]},{"id":"alan","nome":"Alan","nomeCompleto":"Alan","apelido":"El Campeón","idade":18,"status":"vivo","grupo":"rival","ranking":null,"arma":null,"estilo":"Crimen organizado","elemental":null,"descricaoBreve":"Dieciocho años. Líder del crimen organizado de Marelia. El rival que enseñó que hay peleas que no se ganan, solo se sobreviven.","descricaoCompleta":"Dieciocho años. Líder del crimen organizado de una región entera de Marelia. Alan no llegó a donde está por herencia o conexiones. Llegó porque era el chico de la calle que nadie podía doblegar, y cuando el mundo del crimen se dio cuenta, fue solo cuestión de tiempo. Seguridad, cobrador, jefe, jefe del jefe. Un escalón a la vez, cada uno ganado de la única forma que ese mundo reconoce. Kim y Jack pelearon con él durante años. Perdieron. Volvieron. Perdieron de nuevo. Nunca ganaron, pero tampoco se detuvieron nunca, y Alan lo recordó. Cuando la fama de los dos en LDI empieza a salpicar sus negocios, Alan no actúa por ira. Actúa porque la debilidad visible en un mundo como el suyo tiene precio. El encuentro final no termina en derrota ni en victoria. Termina en un empate que ambos saben que significa respeto, y en un trato: váyanse de Marelia, preferiblemente del país, y él garantiza la protección de los que se quedan atrás. No es antagonista. Es el rival que enseñó que hay peleas que no se ganan, solo se sobreviven.","frase":"","imagem":"/assets/images/characters/alan.png","relacoes":[{"personagem":"Kim","tipo":"Rival histórico / respeto mutuo"},{"personagem":"Jack","tipo":"Rival histórico / respeto mutuo"}]}]`)};function r(){let{locale:t}=e();return n[t]||n.pt}function i(e){return r().find(t=>t.id===e)||null}var a={pt:{protagonista:`PROTAGONISTAS`,rival:`RIVAIS`,apoio:`APOIO`,antagonista:`ANTAGONISTAS`},en:{protagonist:`PROTAGONISTS`,rival:`RIVALS`,supporting:`SUPPORTING`,antagonist:`ANTAGONISTS`},es:{protagonista:`PROTAGONISTAS`,rival:`RIVALES`,apoyo:`APOYO`,antagonista:`ANTAGONISTAS`}};function o(){let{locale:t}=e(),r=n[t]||n.pt,i=a[t]||a.pt,o={};for(let e of r){let t=e.grupo;o[t]||(o[t]=[]),o[t].push(e)}let s=t===`en`?[`protagonist`,`rival`,`supporting`,`antagonist`]:[`protagonista`,`rival`,`apoio`,`antagonista`],c=[];for(let e of s)o[e]&&c.push({label:i[e]||e,items:o[e]});return c}export{r as n,o as r,i as t};
//# sourceMappingURL=usePersonagens-C40pL1RU.js.map